from math import gcd
from functools import reduce

def maxScore(nums: List[int]) -> int:
    n = len(nums)

    # Helper to compute LCM of a list
    def lcm(a, b):
        return a * b // gcd(a, b)

    def list_lcm(lst):
        if not lst:
            return 0
        return reduce(lcm, lst)

    def list_gcd(lst):
        if not lst:
            return 0
        return reduce(gcd, lst)

    # Consider removing 0 elements
    def factor_score(arr):
        if not arr:
            return 0
        l = list_lcm(arr)
        g = list_gcd(arr)
        return l * g

    best = factor_score(nums)

    # Consider removing each element one by one
    for i in range(n):
        # Create a new list without element i
        arr = nums[:i] + nums[i+1:]
        if not arr:
            score = 0
        else:
            score = factor_score(arr)
        if score > best:
            best = score

    return best
