from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    if n == 0:
        return 0

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for i in range(n):
        set_i = set(properties[i])
        for j in range(i + 1, n):
            common = 0
            for val in properties[j]:
                if val in set_i:
                    common += 1
                    if common >= k:
                        break
            if common >= k:
                union(i, j)

    return len(set(find(i) for i in range(n)))
