def numberOfComponents(properties, k):
    n = len(properties)

    def intersect(a, b):
        # Count distinct integers common to both arrays
        return len(set(a) & set(b))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if intersect(properties[i], properties[j]) >= k:
                adj[i].append(j)
                adj[j].append(i)

    # Find connected components using DFS/BFS
    visited = [False] * n
    components = 0

    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    return components
