from typing import List

def isZeroArray(nums: List[int], queries: List[List[int]]) -> bool:
    n = len(nums)
    # Use difference array to track how many times each index is covered by queries
    # diff[i] represents the change at position i
    diff = [0] * (n + 1)

    for l, r in queries:
        diff[l] += 1
        if r + 1 < n:
            diff[r + 1] -= 1

    # Build the count array from difference array
    counts = [0] * n
    if n > 0:
        counts[0] = diff[0]
        for i in range(1, n):
            counts[i] = counts[i - 1] + diff[i]

    # Check if for each index, the number of times it's covered >= nums[i]
    for i in range(n):
        if counts[i] < nums[i]:
            return False

    return True
