from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[i][j][k] = maximum coins we can have at cell (i,j) having used k neutralizations (k in 0,1,2)
    # We can use a 3D array, but since m,n can be up to 500, that's 500*500*3 = 750,000 entries which is fine.

    # Initialize with a very small value (negative infinity)
    NEG_INF = float('-inf')

    # dp[i][j][k] for i in 0..m-1, j in 0..n-1, k in 0..2
    dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

    # Starting cell (0,0)
    start_val = coins[0][0]
    for k in range(3):
        if start_val >= 0:
            dp[0][0][k] = start_val
        else:
            # If start_val is negative (robber), we can use a neutralization or not
            # If we use a neutralization (k >= 1), the robber is neutralized, so we gain 0
            # If we don't use, we lose |start_val| coins
            if k >= 1:
                dp[0][0][k] = 0
            else:
                dp[0][0][k] = start_val

    # Fill the dp table
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            val = coins[i][j]

            # Possible previous cells: from top (i-1, j) or from left (i, j-1)
            prev_options = []
            if i > 0:
                prev_options.append((i-1, j))
            if j > 0:
                prev_options.append((i, j-1))

            for pi, pj in prev_options:
                for k_prev in range(3):
                    if dp[pi][pj][k_prev] == NEG_INF:
                        continue

                    if val >= 0:
                        # No robber, just add val
                        dp[i][j][k_prev] = max(dp[i][j][k_prev], dp[pi][pj][k_prev] + val)
                    else:
                        # Robber present
                        # Option 1: Don't use neutralization, lose |val| coins
                        dp[i][j][k_prev] = max(dp[i][j][k_prev], dp[pi][pj][k_prev] + val)
                        # Option 2: Use a neutralization (if we have any left)
                        if k_prev < 2:
                            k_new = k_prev + 1
                            # When neutralized, the robber doesn't steal, so we gain 0 from this cell
                            dp[i][j][k_new] = max(dp[i][j][k_new], dp[pi][pj][k_prev])

    # The answer is the maximum over all k at the bottom-right cell
    return max(dp[m-1][n-1])
