from typing import List

def resultsArray(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    results = []
    for i in range(n - k + 1):
        window = nums[i:i+k]
        if window == sorted(window) and len(set(window)) == k:
            results.append(max(window))
